<?php $title='Features'; $editableFlags=array_values(array_filter($flags, function ($flag) { return !empty($flag['can_edit']); })); ?>
<div class="page-head"><div><span class="eyebrow">FEATURE MANAGEMENT</span><h1>Features</h1><p><?= $isTestEnvironment?'Bản nháp':'Trạng thái đang phát hành' ?> v<?= (int)($draft['version_number'] ?? 0) ?> · <?= e($environment['name']) ?>. Mọi tính năng được chọn từ thư viện do Admin quản lý.</p></div><a class="button" href="<?= e(url('versions')) ?>">Lịch sử phiên bản</a></div>
<?php if(!$isTestEnvironment): ?><div class="notice info">Môi trường phát hành đang ở chế độ chỉ xem. Hãy chuyển sang Staging để thay đổi cấu hình. Kill Switch khẩn cấp vẫn có thể dùng để dừng tính năng ngay lập tức.</div><?php endif; ?>
<?php if($isTestEnvironment && $draft && $draft['status']==='draft' && $canPublish): ?><section class="panel"><div class="panel-head"><div><h2>Phát hành thay đổi</h2><p>Phát hành toàn bộ cấu hình trong bản nháp v<?= (int)$draft['version_number'] ?> sang môi trường Phát hành và ghi lại phiên bản ở cả hai môi trường.</p></div></div><form method="post" action="<?= e(url('versions/publish')) ?>" class="inline-form"><?= csrf_field() ?><input type="hidden" name="version_id" value="<?= (int)$draft['id'] ?>"><input name="reason" required placeholder="Lý do phát hành"><button class="button primary" type="submit">Phát hành v<?= (int)$draft['version_number'] ?></button></form></section><?php endif; ?>
<?php if($isTestEnvironment && $editableFlags): ?><section class="panel"><div class="panel-head"><div><h2>Lưu bản nháp</h2><p>Chọn trạng thái cho các Feature bên dưới, sau đó lưu tất cả thay đổi cùng lúc.</p></div></div><form method="post" action="<?= e(url('flags/save-draft')) ?>" class="inline-form" id="featureDraftForm"><?= csrf_field() ?><?php foreach($editableFlags as $flag): $initialEnabled=$flag['forced_value']!==null?(bool)$flag['forced_value']:(bool)$flag['default_value']; ?><input type="hidden" name="features[<?= (int)$flag['id'] ?>][enabled]" value="<?= $initialEnabled?'1':'0' ?>" data-feature-state="<?= (int)$flag['id'] ?>"><input type="hidden" name="features[<?= (int)$flag['id'] ?>][original_enabled]" value="<?= $initialEnabled?'1':'0' ?>" data-feature-original="<?= (int)$flag['id'] ?>"><?php endforeach; ?><input name="reason" maxlength="500" placeholder="Lý do thay đổi (không bắt buộc)"><button class="button primary" type="submit" id="saveFeatureDraft" disabled>Lưu nháp</button></form></section><?php endif; ?>
<section class="panel"><div class="panel-head"><div><h2>Features trong dự án</h2><p><?= $isTestEnvironment?'Trạng thái chỉnh sửa được lưu vào bản nháp bằng nút Lưu nháp chung. Fallback tự động theo giá trị mặc định của mỗi Feature.':'Trạng thái dưới đây là cấu hình đang phát hành. Fallback tự động theo giá trị mặc định của mỗi Feature.' ?></p></div><?php if($draft): ?><span class="pill <?= $draft['status']==='draft'?'amber':'green' ?>"><?= e(strtoupper($draft['status'])) ?> v<?= (int)$draft['version_number'] ?></span><?php endif; ?></div>
<?php if(!$flags): ?><p class="empty">Dự án chưa dùng tính năng nào từ thư viện Admin.</p><?php else: ?><div class="feature-list">
<?php foreach($flags as $flag): $isEmergencyStopped=(bool)$flag['emergency_kill_switch']; $isEnabled=$flag['forced_value']!==null?(bool)$flag['forced_value']:(bool)$flag['default_value']; ?>
<div class="feature-row"><div class="feature-info"><strong><?= e($flag['name']) ?></strong><code><?= e($flag['key']) ?></code><small><?= e($flag['description']) ?></small></div>
<span class="pill <?= $isEmergencyStopped?'red':($isEnabled?'green':'gray') ?>" data-feature-status="<?= (int)$flag['id'] ?>" data-emergency="<?= $isEmergencyStopped?'1':'0' ?>"><?= $isEmergencyStopped?'DỪNG KHẨN CẤP':($isEnabled?'ĐANG BẬT':'ĐANG TẮT') ?></span>
<?php if($flag['can_edit']): ?><button class="button" type="button" data-feature-toggle="<?= (int)$flag['id'] ?>" data-enabled="<?= $isEnabled?'1':'0' ?>"><?= $isEnabled?'Tắt trong bản nháp':'Bật trong bản nháp' ?></button><?php endif; ?>
<?php if($canEmergencyToggle): ?><form method="post" action="<?= e(url('flags/kill-switch')) ?>"><?= csrf_field() ?><input type="hidden" name="flag_id" value="<?= (int)$flag['id'] ?>"><button class="button <?= $isEmergencyStopped?'':'danger' ?>" type="submit" name="enabled" value="<?= $isEmergencyStopped?'0':'1' ?>" onclick="return confirm('<?= $isEmergencyStopped?'Gỡ Kill Switch và cho phép feature tuân theo cấu hình đã phát hành?':'Kích hoạt Kill Switch ngay lập tức? Feature sẽ bị dừng trên mọi môi trường.' ?>')"><?= $isEmergencyStopped?'Gỡ Kill Switch':'Kill Switch khẩn cấp' ?></button></form><?php endif; ?>
<?php if(!$flag['can_edit'] && !$canEmergencyToggle): ?><span class="pill gray">Chỉ xem</span><?php endif; ?></div>
<?php endforeach; ?></div><?php endif; ?></section>
<?php if($isTestEnvironment && ($user['account_type']??'')==='owner' && App\Support\Auth::isAdmin($projectId) && $availableCatalogFeatures): ?><section class="panel"><div class="panel-head"><div><h2>Thêm tính năng có sẵn vào bản nháp</h2><p>Chọn tính năng do Admin cung cấp; thay đổi chỉ nằm trong Staging cho đến khi phát hành.</p></div></div><form method="post" action="<?= e(url('flags/add-from-catalog')) ?>" class="inline-form"><?= csrf_field() ?><select name="catalog_feature_id" required><option value="">Chọn tính năng</option><?php foreach($availableCatalogFeatures as $feature): ?><option value="<?= (int)$feature['id'] ?>"><?= e($feature['name']) ?> · <?= e($feature['key']) ?></option><?php endforeach; ?></select><button class="button primary" type="submit">Thêm vào bản nháp</button></form></section><?php endif; ?>
<?php if($isTestEnvironment && $editableFlags): ?><script>(function(){var form=document.getElementById('featureDraftForm'),save=document.getElementById('saveFeatureDraft');function changed(){var any=false;document.querySelectorAll('[data-feature-state]').forEach(function(state){var original=document.querySelector('[data-feature-original="'+state.dataset.featureState+'"]');if(original&&state.value!==original.value)any=true;});save.disabled=!any;}document.querySelectorAll('[data-feature-toggle]').forEach(function(button){button.addEventListener('click',function(){var id=button.dataset.featureToggle,state=document.querySelector('[data-feature-state="'+id+'"]'),status=document.querySelector('[data-feature-status="'+id+'"]');if(!state)return;state.value=state.value==='1'?'0':'1';var enabled=state.value==='1';button.dataset.enabled=state.value;button.textContent=enabled?'Tắt trong bản nháp':'Bật trong bản nháp';if(status&&status.dataset.emergency!=='1'){status.textContent=enabled?'ĐANG BẬT':'ĐANG TẮT';status.className='pill '+(enabled?'green':'gray');}changed();});});form.addEventListener('submit',function(){save.disabled=true;});})();</script><?php endif; ?>
